    out = [row[:] for row in grid]

    # Find a full row or column of marker color 2.
    marker_row = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    marker_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)

    # The non-background, non-marker color is the movable object.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    obj_colors = {v for row in grid for v in row if v != bg and v != 2}
    if not obj_colors:
        return out
    obj = next(iter(obj_colors))
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj]

    if marker_row is not None:
        top = min(r for r, c in cells)
        bottom = max(r for r, c in cells)
        if marker_row > bottom:
            shift = marker_row - 1 - bottom
            dr = shift
            line_r = top + shift - 1
        else:
            shift = top - (marker_row + 1)
            dr = -shift
            line_r = top - shift + 1
        # Clear original object, shift it toward the marker, and draw the trail line.
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r + dr][c] = obj
        for c in range(w):
            if out[line_r][c] != 2:
                out[line_r][c] = 8

    elif marker_col is not None:
        left = min(c for r, c in cells)
        right = max(c for r, c in cells)
        if marker_col > right:
            shift = marker_col - 1 - right
            dc = shift
            line_c = left + shift - 1
        else:
            shift = left - (marker_col + 1)
            dc = -shift
            line_c = left - shift + 1
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r][c + dc] = obj
        for r in range(h):
            if out[r][line_c] != 2:
