def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Background is the most frequent color; 2 is the marker line.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    marker_row = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    marker_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)

    obj_cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] != bg and grid[r][c] != 2]
    if not obj_cells:
        return out

    minr = min(r for r, c in obj_cells)
    maxr = max(r for r, c in obj_cells)
    minc = min(c for r, c in obj_cells)
    maxc = max(c for r, c in obj_cells)

    dr = dc = 0
    if marker_row is not None:
        if marker_row > maxr:
            dr = marker_row - 1 - maxr
            trail_row = minr + dr - 1
        else:
            dr = marker_row + 1 - minr
            trail_row = maxr + dr + 1
        for r, c in obj_cells:
            out[r][c] = bg
        for r, c in obj_cells:
            out[r + dr][c] = grid[r][c]
        if 0 <= trail_row < h:
            for c in range(w):
                if out[trail_row][c] != 2:
                    out[trail_row][c] = 8

    elif marker_col is not None:
        if marker_col > maxc:
            dc = marker_col - 1 - maxc
            trail_col = minc + dc - 1
        else:
            dc = marker_col + 1 - minc
            trail_col = maxc + dc + 1
        for r, c in obj_cells:
            out[r][c] = bg
        for r, c in obj_cells:
            out[r][c + dc] = grid[r][c]
        if 0 <= trail_col < w:
            for r in range(h):
                if out[r][trail_col] != 2:
                    out[r][trail_col] = 8

    return out
